import time
from functools import wraps

def retry(max_attempts=3, backoff_factor=0.5):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            delay = 0
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    delay = backoff_factor * (2 ** attempts)
                    print(f'Task failed (attempt {attempts}/{max_attempts}). Retrying in {delay:.2f} seconds...')
                    time.sleep(delay)
                    if attempts == max_attempts:
                        print(f'Task failed after {max_attempts} attempts. Sending alert...')
                        # Send alert
                        raise
        return wrapper
    return decorator

# Example usage:
@retry(max_attempts=5, backoff_factor=0.25)
def example_task():
    # Simulate a failing task
    raise Exception('Task failed')

task = example_task()
